function memoize(fn) {
  const cache = new Map();
  return (n) => {
    if (!cache.has(n)) cache.set(n, fn(n));
    return cache.get(n);
  };
}

let discount = 10;
const seen = [];
const price = memoize((amount) => {
  seen.push(amount);
  return amount - discount;
});

console.log(price(50));
discount = 20;
console.log(price(50));
console.log(price(60));
console.log(seen.join(","));
